function arm(sx,sy,a,len,col,skin){const r=a*Math.PI/180;const ex=sx-Math.sin(r)*len,ey=sy+Math.cos(r)*len;return [['rect',`x="${sx-9}" y="${sy}" width="18" height="${len}" rx="9" transform="rotate(${a} ${sx} ${sy})"`,col],['circle',`cx="${ex.toFixed(1)}" cy="${ey.toFixed(1)}" r="8"`,skin]];}
function handPos(sx,sy,a,len){const r=a*Math.PI/180;return [sx-Math.sin(r)*len,sy+Math.cos(r)*len];}
function legs(pose,xl,xr,hy,len,w,col,shoe){const a=pose==='walking'?14:0;const s=[];for(const [x,ang] of [[xl,a],[xr,-a]]){const [ex,ey]=handPos(x,hy,ang,len);s.push(['rect',`x="${x-w/2}" y="${hy}" width="${w}" height="${len}" rx="4" transform="rotate(${ang} ${x} ${hy})"`,col]);s.push(['ellipse',`cx="${ex.toFixed(1)}" cy="${(ey+2).toFixed(1)}" rx="${w/2+6}" ry="7"`,shoe]);}return s;}
