function defsFor(html){const ids=new Set();const re=/href="#([a-z0-9_]+)"/g;let m;while((m=re.exec(html)))if(A[m[1]])ids.add(m[1]);for(const id of [...ids]){const mm=A[id].g.match(/href="#([a-z0-9_]+)"/g);if(mm)mm.forEach(x=>ids.add(x.slice(7,-1)));}let g='';for(const id of ids)g+=`<g id="${id}">${A[id].g}</g>`;return `<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>${BASEDEFS}${g}</defs></svg>`;}
