const coin=(s=22)=>`<div style="width:${s}px;height:${s}px;border-radius:50%;background:${C.gold};box-shadow:inset 0 0 0 ${s>20?2.5:2}px ${C.ink};flex-shrink:0"></div>`;
const gem=(s=16)=>`<div style="width:${s}px;height:${s}px;transform:rotate(45deg);border-radius:3px;background:${C.verd};box-shadow:inset 0 0 0 2px ${C.ink};flex-shrink:0;margin:0 2px"></div>`;
const ISL=`<div style="position:absolute;left:50%;top:11px;transform:translateX(-50%);width:120px;height:34px;border-radius:20px;background:#000;z-index:20"></div><div style="position:absolute;left:50%;bottom:8px;transform:translateX(-50%);width:134px;height:5px;border-radius:3px;background:${C.ink};z-index:20"></div>`;
function phone(inner,bg=C.paper){return `<div style="width:390px;height:844px;border:10px solid #2A1C16;border-radius:58px;position:relative;overflow:hidden;background:${bg};flex-shrink:0;box-shadow:0 30px 60px -30px rgba(74,44,32,.5)">${inner}${ISL}</div>`;}
function topbar(title,{left='back',right=''}={}){const l=left?`<div style="width:44px;height:44px;border-radius:50%;background:${C.card};border:2.5px solid ${C.ink};box-sizing:border-box;display:flex;align-items:center;justify-content:center;flex-shrink:0">${icon(left,20,'none')}</div>`:'<div style="width:44px"></div>';return `<div style="position:absolute;left:16px;right:16px;top:54px;height:48px;display:flex;align-items:center;gap:10px;z-index:5">${l}<div style="flex:1;text-align:center;font-size:21px;font-weight:800;letter-spacing:-.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${title}</div>${right||'<div style="width:44px"></div>'}</div>`;}
function pill(content,{bg=C.card,border=C.ink}={}){return `<div style="display:flex;align-items:center;gap:6px;height:36px;box-sizing:border-box;background:${bg};border:2.5px solid ${border};border-radius:18px;padding:0 12px 0 4px;${MONO};font-weight:600;font-size:15px;white-space:nowrap;flex-shrink:0">${content}</div>`;}
function btnP(label,{h=56,full=true,dis=false,extra='',fs=17}={}){if(dis)return `<div style="height:${h}px;${full?'width:100%;':''}box-sizing:border-box;padding:0 20px;border-radius:16px;border:3.5px dashed ${C.dis};background:${C.sunk};display:flex;align-items:center;justify-content:center;gap:8px;font-size:${fs}px;font-weight:800;color:${C.ink2};text-align:center">${icon('lock',16,'none',C.ink2,2.4)}${label}</div>`;return `<div style="height:${h}px;${full?'width:100%;':''}box-sizing:border-box;padding:0 20px;border-radius:16px;border:3.5px solid ${C.ink};background:${C.gold};box-shadow:4px 4px 0 ${C.sang};display:flex;align-items:center;justify-content:center;gap:8px;font-size:${fs}px;font-weight:800;text-align:center;cursor:pointer;user-select:none" style-active="transform:translate(3px,3px);box-shadow:1px 1px 0 ${C.sang}">${label}${extra}</div>`;}
function btnS(label,{h=48,full=true}={}){return `<div style="height:${h}px;${full?'width:100%;':''}box-sizing:border-box;padding:0 18px;border-radius:16px;border:2.5px solid ${C.ink};background:${C.card};box-shadow:2px 2px 0 ${C.ink};display:flex;align-items:center;justify-content:center;gap:8px;font-size:16px;font-weight:800;cursor:pointer" style-active="transform:translate(2px,2px);box-shadow:0 0 0 ${C.ink}">${label}</div>`;}
function btnAd(label,reward,{h=56,full=true}={}){return `<div style="height:${h}px;${full?'width:100%;':''}box-sizing:border-box;padding:0 8px 0 16px;border-radius:16px;border:3.5px solid ${C.ink};background:${C.verd};box-shadow:4px 4px 0 ${C.gold};display:flex;align-items:center;justify-content:center;gap:10px;color:${C.card};font-size:17px;font-weight:800;cursor:pointer" style-active="transform:translate(3px,3px);box-shadow:1px 1px 0 ${C.gold}">${icon('video',24,'none',C.card,2.4)}${label}<div style="height:36px;padding:0 10px;border-radius:10px;background:${C.card};color:${C.ink};display:flex;align-items:center;gap:6px;${MONO};font-weight:600;font-size:15px;white-space:nowrap">${reward}</div></div>`;}
const RAR={common:{bg:C.card,sh:`inset 0 0 0 2px ${C.ink}`,pips:1},rare:{bg:C.card,sh:`inset 0 0 0 2px ${C.ink},inset 0 0 0 5px ${C.card},inset 0 0 0 7px ${C.ink}`,pips:2},refined:{bg:`${C.card};background-image:radial-gradient(rgba(63,122,110,.45) 1.3px,transparent 1.5px);background-size:6px 6px`,sh:`inset 0 0 0 2px ${C.ink},inset 0 0 0 5px ${C.card},inset 0 0 0 7px ${C.verd}`,pips:3},legendary:{bg:`#F6D27A;background-image:radial-gradient(rgba(201,83,58,.5) 1.3px,transparent 1.5px);background-size:6px 6px`,sh:`inset 0 0 0 3.5px ${C.ink}`,pips:4}};
function pips(n){let s='';for(let i=0;i<Math.min(n,3);i++)s+=`<div style="width:6px;height:6px;border-radius:50%;background:${C.ink}"></div>`;if(n>3)s+=`<div style="width:7px;height:7px;transform:rotate(45deg);background:${C.ink}"></div>`;return `<div style="display:flex;gap:3px;align-items:center">${s}</div>`;}
function dishCard(id,name,{r='common',w=104,state='normal',price='',time=''}={}){const R=RAR[r];const s=w-24;let art=sym(id,s);let bg=R.bg,sh=R.sh,extra='',nameCol=C.ink,op='';if(state==='locked'){bg=C.sunk;sh=`inset 0 0 0 2px ${C.dis}`;art=`<svg viewBox="${A[id].vb}" width="${s}" height="${s}" style="filter:brightness(0);opacity:.22"><use href="#${id}"></use></svg><div style="position:absolute;font-size:28px;font-weight:800;color:${C.ink2}">?</div>`;name='???';nameCol=C.ink2;}
if(state==='new')extra=`<div style="position:absolute;top:-9px;left:-6px;height:20px;padding:0 7px;border-radius:6px;background:${C.sang};border:2px solid ${C.card};color:${C.card};font-size:11px;font-weight:800;display:flex;align-items:center">Nouveau</div>`;
if(state==='selected'){sh+=`,5px 5px 0 ${C.sang}`;extra=`<div style="position:absolute;top:-8px;right:-8px;width:24px;height:24px;border-radius:50%;background:${C.ink};display:flex;align-items:center;justify-content:center">${icon('check',14,'none',C.card,3.4)}</div>`;}
if(state==='menu')op='opacity:.5;';
const rad=r==='legendary'?'clip-path:polygon(12% 0,88% 0,100% 12%,100% 88%,88% 100%,12% 100%,0 88%,0 12%);':'border-radius:12px;';
const meta=(price||time)&&state!=='locked'?`<div style="display:flex;gap:8px;${MONO};font-size:11px;font-weight:600;align-items:center">${price?`<span style="display:flex;align-items:center;gap:3px">${coin(11)}${price}</span>`:''}${time?`<span>${time}</span>`:''}</div>`:'';
return `<div style="width:${w}px;display:flex;flex-direction:column;gap:6px;flex-shrink:0"><div style="position:relative;width:${w}px;height:${w}px;${op}"><div style="position:absolute;inset:0;${rad}background:${bg};box-shadow:${sh};display:flex;align-items:center;justify-content:center">${art}</div>${extra}</div><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:4px"><div style="font-size:14px;font-weight:700;line-height:1.2;color:${nameCol};min-width:0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">${state==='menu'?'Au menu':name}</div>${state==='locked'?'':pips(R.pips)}</div>${meta}</div>`;}
function ingTile(id,name,{state='normal',s=72}={}){let bg=C.card,b=`2.5px solid ${C.ink}`,x='',art=sym(id,s-18),nm=name,col=C.ink,shadow='';if(state==='selected'){bg=C.goldS;shadow=`box-shadow:3px 3px 0 ${C.sang};`;x=`<div style="position:absolute;top:-6px;right:-6px;width:22px;height:22px;border-radius:50%;background:${C.ink};display:flex;align-items:center;justify-content:center">${icon('check',12,'none',C.card,3.4)}</div>`;}
if(state==='locked'){bg=C.sunk;b=`2.5px dashed ${C.dis}`;art=`<div style="opacity:.3;filter:brightness(0)">${sym(id,s-26)}</div>`;x=`<div style="position:absolute;bottom:-4px;right:-4px;width:24px;height:24px;border-radius:50%;background:${C.card};border:2px solid ${C.dis};display:flex;align-items:center;justify-content:center">${icon('lock',13,'none',C.ink2,2.6)}</div>`;col=C.ink2;}
if(state==='new')x=`<div style="position:absolute;top:-6px;right:-10px;height:18px;padding:0 5px;border-radius:5px;background:${C.sang};border:2px solid ${C.card};color:${C.card};font-size:10px;font-weight:800;display:flex;align-items:center">Nouv.</div>`;
if(state==='used'){bg=C.sunk;b=`2.5px solid ${C.dis}`;art=`<div style="opacity:.45">${sym(id,s-18)}</div>`;col=C.ink2;}
return `<div style="display:flex;flex-direction:column;align-items:center;gap:4px;width:${s+8}px"><div style="position:relative;width:${s}px;height:${s}px;border-radius:50%;background:${bg};border:${b};box-sizing:border-box;display:flex;align-items:center;justify-content:center;${shadow}">${art}${x}</div><div style="font-size:12px;font-weight:700;color:${col};text-align:center;line-height:1.15">${nm}</div></div>`;}
function gauge(v,max=5,{h=12}={}){let s='';for(let i=0;i<max;i++){const f=Math.max(0,Math.min(1,v-i));s+=`<div style="flex:1;height:${h}px;border-radius:${h/2}px;background:${f>=1?C.sang:f>0?`linear-gradient(90deg,${C.sang} ${f*100}%,${C.sunk} ${f*100}%)`:C.sunk};box-shadow:inset 0 0 0 2px ${f>0?C.ink:C.dis}"></div>`;}return `<div style="display:flex;gap:4px">${s}</div>`;}
function bar(pct,{h=12,col=C.gold}={}){return `<div style="height:${h}px;border-radius:${h/2}px;background:${C.sunk};box-shadow:inset 0 0 0 2px ${C.ink};overflow:hidden;flex:1"><div style="width:${pct}%;height:100%;background-color:${col};background-image:radial-gradient(rgba(74,44,32,.35) 1.1px,transparent 1.3px);background-size:4px 4px;box-shadow:inset 0 0 0 2px ${C.ink}"></div></div>`;}
function tabs(items,active=0){return `<div style="display:flex;gap:4px;padding:4px;border-radius:14px;background:${C.sunk};box-shadow:inset 0 0 0 2px ${C.ink}">${items.map((t,i)=>`<div style="flex:1;height:36px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:13px;white-space:nowrap;padding:0 4px;${i===active?`background:${C.card};box-shadow:inset 0 0 0 2.5px ${C.ink},2px 2px 0 ${C.ink};font-weight:800`:`font-weight:700;color:${C.ink2}`}">${t}</div>`).join('')}</div>`;}
function portrait(id,s=64,bg=C.gold){return `<div style="width:${s}px;height:${s}px;border-radius:50%;overflow:hidden;background-color:${bg};background-image:radial-gradient(rgba(201,83,58,.55) 1.2px,transparent 1.4px);background-size:5px 5px;box-shadow:inset 0 0 0 ${s>50?3:2.5}px ${C.ink};flex-shrink:0;display:flex;align-items:flex-end;justify-content:center">${sym('char_'+id+'_portrait',s*0.96,s*1.04,'margin-bottom:-2px')}</div>`;}
const scrim=`<div style="position:absolute;inset:0;background:rgba(42,24,16,.55);z-index:8"></div>`;
function frame(id,title,content,note=''){return `<div id="${id}" style="display:flex;flex-direction:column;gap:12px;width:410px;flex-shrink:0"><div style="display:flex;gap:10px;align-items:center"><div style="${MONO};font-weight:600;font-size:13px;background:${C.ink};color:${C.paper};border-radius:6px;padding:4px 8px;flex-shrink:0">${id}</div><div style="font-weight:800;font-size:17px;line-height:1.2">${title}</div></div>${content}${note?`<div style="font-size:14px;line-height:1.5;color:${C.ink2};text-wrap:pretty">${note}</div>`:''}</div>`;}
function section(label,kicker,title,sub,inner,{gap=48}={}){return `<section data-screen-label="${label}" style="padding:64px 72px 24px;display:flex;flex-direction:column;gap:32px"><div style="display:flex;flex-direction:column;gap:10px;max-width:1100px"><div style="${MONO};font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:${C.ink2}">${kicker}</div><div style="font-size:40px;font-weight:800;letter-spacing:-.02em;line-height:1.05">${title}</div>${sub?`<div style="font-size:17px;line-height:1.55;color:${C.ink2};max-width:900px;text-wrap:pretty">${sub}</div>`:''}</div><div style="display:flex;flex-wrap:wrap;gap:${gap}px;align-items:flex-start">${inner}</div></section>`;}
function sheet(inner,top=300){return `<div style="position:absolute;left:0;right:0;top:${top}px;bottom:0;background:${C.card};border-top:3.5px solid ${C.ink};border-radius:28px 28px 0 0;box-shadow:0 -8px 24px rgba(74,44,32,.18);z-index:9;display:flex;flex-direction:column;padding:10px 20px 44px;box-sizing:border-box;gap:14px"><div style="align-self:center;width:40px;height:5px;border-radius:3px;background:${C.line};flex-shrink:0"></div>${inner}</div>`;}
function popup(inner,{top=null}={}){return `${scrim}<div style="position:absolute;left:20px;right:20px;${top!==null?`top:${top}px`:'top:50%;transform:translateY(-50%)'};background:${C.card};border:3.5px solid ${C.ink};border-radius:24px;box-shadow:6px 6px 0 ${C.gold};padding:22px;display:flex;flex-direction:column;gap:14px;align-items:center;text-align:center;box-sizing:border-box;z-index:10">${inner}</div>`;}
function toggle(on){return `<div style="width:52px;height:32px;border-radius:16px;background:${on?C.verd:C.sunk};box-shadow:inset 0 0 0 2.5px ${C.ink};position:relative;flex-shrink:0"><div style="position:absolute;top:4px;${on?'right:4px':'left:4px'};width:24px;height:24px;border-radius:50%;background:${C.card};box-shadow:inset 0 0 0 2.5px ${C.ink};display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800">${on?'I':'O'}</div></div>`;}
const HEAD=`<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,400;12..96,500;12..96,700;12..96,800&family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet"><style>body{margin:0;background:#E9DCC4;font-family:'Bricolage Grotesque',system-ui,sans-serif;color:#4A2C20;-webkit-font-smoothing:antialiased}a{color:#A33A24}a:hover{color:#4A2C20}</style>`;
function file(body,{canvas=true,bgBody='#E9DCC4'}={}){const helmet=`<helmet>${canvas?'<meta name="design_doc_mode" content="canvas">':''}${HEAD.replace('#E9DCC4',bgBody)}</helmet>`;const tpl=helmet+defsFor(body)+body;return `<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<script src="./support.js"></script>\n</head>\n<body>\n<x-dc>\n${tpl}\n</x-dc>\n<script type="text/x-dc" data-dc-script>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n</script>\n</body>\n</html>\n`;}
function hud({coins='12,4 k',gems='86',rep='7',top=58}={}){return `<div style="position:absolute;left:16px;right:16px;top:${top}px;display:flex;align-items:center;gap:8px;z-index:6">${pill(coin(26)+coins,{})}${pill(gem(16)+gems)}<div style="flex:1;min-width:0"></div><div style="display:flex;align-items:center;gap:6px;height:36px;box-sizing:border-box;background:${C.card};border:2.5px solid ${C.ink};border-radius:18px;padding:0 12px 0 3px;font-weight:800;font-size:14px;white-space:nowrap;flex-shrink:0"><div style="width:26px;height:26px;border-radius:50%;background:${C.ink};color:${C.paper};display:flex;align-items:center;justify-content:center;font-size:13px">${rep}</div>Réput.</div><div style="width:40px;height:40px;border-radius:50%;background:${C.card};border:2.5px solid ${C.ink};box-sizing:border-box;display:flex;align-items:center;justify-content:center;flex-shrink:0">${icon('settings',20,C.goldS)}</div></div>`;}
function tabbar(active=-1,{dim=false}={}){const it=[['book','Habitués'],['upgrade','Améliorer'],['lab','Labo'],['menu','Menu'],['shop','Boutique']];return `<div style="position:absolute;left:0;right:0;bottom:0;height:140px;background:${C.card};border-top:3.5px solid ${C.ink};border-radius:26px 26px 0 0;display:grid;grid-template-columns:1fr 1fr 1.3fr 1fr 1fr;align-items:start;padding:12px 8px 0;font-weight:800;font-size:12px;z-index:6;box-sizing:border-box">${it.map(([n,l],i)=>i===2?`<div style="display:flex;flex-direction:column;align-items:center;gap:6px;margin-top:-36px"><div style="width:78px;height:78px;border-radius:50%;background:${C.gold};border:3.5px solid ${C.ink};box-shadow:4px 4px 0 ${C.sang};display:flex;align-items:center;justify-content:center;box-sizing:border-box">${icon('lab',36,C.card)}</div><div style="font-size:14px">${l}</div></div>`:`<div style="display:flex;flex-direction:column;align-items:center;gap:6px;padding-top:6px">${icon(n,30)}${l}</div>`).join('')}</div>`;}
return {C,MONO,A,art,reg,sym,defsFor,icon,coin,gem,phone,topbar,pill,btnP,btnS,btnAd,dishCard,ingTile,gauge,bar,tabs,portrait,scrim,frame,section,sheet,popup,toggle,file,hud,tabbar,pips,RAR,ICONS};
